      clearTimeout(timers.wakeTimeout);
      scheduledWakeAtMs = wakeAt.getTime();
      const sleepMs = Math.max(0, wakeAt.getTime() - Date.now());
      timers.wakeTimeout = setTimeout(async () => {
        try {
          timers.wakeTimeout = null;
          scheduledWakeAtMs = null;
